 WHEN (SELECT COUNT(*) FROM (SELECT id FROM system_menu WHERE deleted=b'0' AND status=0 AND type=2 AND path='/mdm/registration-certificate' AND component='dcc/registration-certificate/index/index' AND permission='dcc:registration-certificate:query-current') certificate_page)<>1 THEN 'TARGET_PREFLIGHT_BLOCKED:20261118_registration_certificate_delete_menu:CANONICAL_PAGE_CONFLICT'
